// Usage: node --import tsx compare-reference.mjs MODEL_INDEX.ts CASES_DIR REFERENCE_DIR
// The reference directory must have been generated by the original R code.
import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { verifyUpstream } from './verify-upstream.mjs'

verifyUpstream(path.dirname(fileURLToPath(import.meta.url)))

const modelPath = path.resolve(process.argv[2] ?? 'src/features/forest-drought/model/index.ts')
const casesDir = path.resolve(process.argv[3] ?? 'scripts/forest-drought/reference/cases')
const referenceDir = path.resolve(process.argv[4] ?? 'scripts/forest-drought/reference/generated')
const model = await import(pathToFileURL(modelPath).href)
const tolerance = 1e-10
const manifest = JSON.parse(fs.readFileSync(path.join(casesDir, 'cases.json'), 'utf8'))
let comparisons = 0
let dailyRows = 0
let maximumAbsoluteError = 0
let maximumRelativeError = 0
let maximumCase = null
const metrics = []

function close(actual, expected, label) {
  assert.ok(Number.isFinite(actual) && Number.isFinite(expected), `${label}: non-finite value`)
  const absolute = Math.abs(actual - expected)
  const relative = absolute / Math.max(1, Math.abs(expected))
  comparisons++
  if (absolute > maximumAbsoluteError) { maximumAbsoluteError = absolute; maximumCase = label }
  maximumRelativeError = Math.max(maximumRelativeError, relative)
  assert.ok(relative <= tolerance, `${label}: TypeScript=${actual}, R=${expected}, relative error=${relative}`)
}

const soilsRows = model.readCsv(fs.readFileSync(path.join(referenceDir, 'soils.csv'), 'utf8'))
for (let k = 0; k < 5; k++) {
  const header = soilsRows[0]
  const row = soilsRows[k + 1]
  for (const [tsKey, rKey] of [['afc', 'AFC'], ['awsc', 'AWSC'], ['infiltrationRate', 'infRate']]) {
    close(model.DEFAULT_SOILS[k][tsKey], Number(row[header.indexOf(rKey)]), `default soil ${k + 1} ${rKey}`)
  }
  assert.equal(model.DEFAULT_SOILS[k].label, row[header.indexOf('RSMR')])
}
const classRows = model.readCsv(fs.readFileSync(path.join(referenceDir, 'classes.csv'), 'utf8'))
for (let i = 0; i < 6; i++) {
  close(model.ASMR_CLASSES[i].upper, Number(classRows[i + 1][0]), `class ${i + 1} upper`)
  assert.equal(model.ASMR_CLASSES[i].label, classRows[i + 1][1])
}
for (const name of manifest.cases) {
  const climate = model.parseClimateCsv(fs.readFileSync(path.join(casesDir, `${name}.csv`), 'utf8'))
  for (const latitude of manifest.latitudes) {
    const soils = model.DEFAULT_SOILS.map((soil) => ({ ...soil }))
    if (name === 'lateral') soils[2].infiltrationRate = -10
    const simulation = model.runSimulation({ climate, latitude, soils })
    const rows = model.readCsv(fs.readFileSync(path.join(referenceDir, `${name}-${latitude}.csv`), 'utf8'))
    const header = rows.shift()
    assert.equal(simulation.baseline.daily.length, rows.length)
    const column = (row, field) => Number(row[header.indexOf(field)])
    for (let i = 0; i < rows.length; i++) {
      const actual = simulation.baseline.daily[i]
      const expected = rows[i]
      assert.equal(actual.date, expected[header.indexOf('date')])
      for (const [tsKey, rKey] of [['tav', 'tav'], ['radiation', 'Rn'], ['pet', 'PET'], ['snow', 'snow'], ['snowpack', 'snowbank'], ['potentialWaterBalance', 'pPET']]) {
        close(actual[tsKey], column(expected, rKey), `${name}/${latitude}/${actual.date}/${rKey}`)
      }
      for (let k = 0; k < 5; k++) close(actual.soils[k].ratio, column(expected, `S${k + 1}.ASMR`), `${name}/${latitude}/${actual.date}/S${k + 1}.ASMR`)
    }
    dailyRows += rows.length
    metrics.push({ case: name, latitude, dailyRows: rows.length })
  }
}
const report = { schema: 'forest-drought-r-parity-v1', passed: true, upstreamCommit: manifest.upstreamCommit, tolerance, comparisons, dailyRows, maximumAbsoluteError, maximumRelativeError, maximumCase, cases: metrics }
fs.writeFileSync(path.join(referenceDir, 'comparison-report.json'), JSON.stringify(report, null, 2) + '\n')
console.log(JSON.stringify(report, null, 2))
